typedef struct Node {
    int data;
    struct Node* next;
} Node;
typedef Node SinglyNode;

Node* createNode(int data) {
    Node* n = (Node*)malloc(sizeof(Node));
    if (!n) return NULL;
    n->data = data;
    n->next = NULL;
    return n;
}

void singly_list_insert_head(Node** head, int val) {
    Node* n = (Node*)malloc(sizeof(Node));
    if (!n) return;
    n->data = val;
    n->next = *head;
    *head = n;
}

void singly_list_insert_tail(Node** head, int val) {
    Node* n = (Node*)malloc(sizeof(Node));
    if (!n) return;
    n->data = val;
    n->next = NULL;
    if (!*head) { *head = n; return; }
    Node* cur = *head;
    while (cur->next) cur = cur->next;
    cur->next = n;
}

int singly_list_delete_head(Node** head) {
    if (!head || !*head) return -1;
    Node* tmp = *head;
    *head = (*head)->next;
    free(tmp);
    return 0;
}

int singly_list_delete_value(Node** head, int val) {
    if (!head || !*head) return -1;
    if ((*head)->data == val) {
        Node* tmp = *head;
        *head = (*head)->next;
        free(tmp);
        return 0;
    }
    Node* cur = *head;
    while (cur->next && cur->next->data != val) cur = cur->next;
    if (!cur->next) return -1;
    Node* tmp = cur->next;
    cur->next = tmp->next;
    free(tmp);
    return 0;
}

void singly_list_reverse(Node** head) {
    Node* prev = NULL;
    Node* cur = *head;
    while (cur) {
        Node* nxt = cur->next;
        cur->next = prev;
        prev = cur;
        cur = nxt;
    }
    *head = prev;
}

Node* singly_list_find_middle(Node* head) {
    if (!head) return NULL;
    Node* slow = head;
    Node* fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
    }
    return slow;
}

bool singly_list_has_cycle(const Node* head) {
    const Node* slow = head;
    const Node* fast = head;
    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) return true;
    }
    return false;
}

void singly_list_print(const Node* head) {
    printf("[");
    while (head) {
        printf("%d%s", head->data, head->next ? " -> " : "");
        head = head->next;
    }
    printf("]\n");
}

void singly_list_free(Node** head) {
    if (!head) return;
    Node* cur = *head;
    while (cur) {
        Node* tmp = cur;
        cur = cur->next;
        free(tmp);
    }
    *head = NULL;
}

