typedef struct DoublyNode {
    int data;
    struct DoublyNode* prev;
    struct DoublyNode* next;
} DoublyNode;

DoublyNode* doubly_list_create_node(int val) {
    DoublyNode* n = (DoublyNode*)malloc(sizeof(DoublyNode));
    if (!n) return NULL;
    n->data = val; n->prev = n->next = NULL; return n;
}

void doubly_list_insert_head(DoublyNode** head, int val) {
    DoublyNode* n = doubly_list_create_node(val);
    if (!n) return;
    n->next = *head;
    if (*head) (*head)->prev = n;
    *head = n;
}

void doubly_list_insert_tail(DoublyNode** head, int val) {
    DoublyNode* n = doubly_list_create_node(val);
    if (!n) return;
    if (!*head) { *head = n; return; }
    DoublyNode* cur = *head;
    while (cur->next) cur = cur->next;
    cur->next = n;
    n->prev = cur;
}

void doubly_list_delete_node(DoublyNode** head, DoublyNode* target) {
    if (!head || !*head || !target) return;
    if (*head == target) *head = target->next;
    if (target->next) target->next->prev = target->prev;
    if (target->prev) target->prev->next = target->next;
    free(target);
}

