void circular_doubly_insert_head(DoublyNode** head, int val) {
    DoublyNode* n = (DoublyNode*)malloc(sizeof(DoublyNode));
    if (!n) return;
    n->data = val;
    if (!*head) { n->next = n->prev = n; *head = n; return; }
    DoublyNode* tail = (*head)->prev;
    n->next = *head; n->prev = tail;
    tail->next = (*head)->prev = n;
    *head = n;
}

